def count_divisible_substrings(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            last_digit = int(substring[-1])
            if last_digit != 0 and int(substring) % last_digit == 0:
                count += 1
    return count

# Example usage:
# print(count_divisible_substrings("12936"))

