import math
from collections import defaultdict, deque

class Solution:
    def countConnectedComponents(self, nums, threshold):
        n = len(nums)
        graph = defaultdict(list)

        # Function to check if lcm(a, b) <= threshold
        def is_connected(a, b):
            return (a * b) // math.gcd(a, b) <= threshold

        # Build the graph
        for i in range(n):
            for j in range(i + 1, n):
                if is_connected(nums[i], nums[j]):
                    graph[i].append(j)
                    graph[j].append(i)

        # Find connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components

