    def countConnectedComponents(self, nums, threshold):
        n = len(nums)
        graph = defaultdict(list)

        # Function to check if lcm(a, b) <= threshold
        def is_connected(a, b):
            return (a * b) // math.gcd(a, b) <= threshold

        # Build the graph
        for i in range(n):
